def verify(tasks, rd=None):
    import research.campaigns.hp.dgp_paths as dgp_paths
    for t in tasks: t['model'] = dgp_paths.resolve_input(t['model'], rd or RD, t['model_sha256']); assert sha(t['model'] + '.evid') == t['evid_sha256'], t['name']; t['verified_now'] = True
    return tasks

def historical_completions_24():
    """the 24 historical DGP6 completions (PROTOCOL section 3: 'the 24 historical DGP6 passes') = the REPAIRED completion set of the DGP6 main panel (RESULTS.json verdict_inputs.main.complete; identical across the four DGP6 arms -- asserted)"""
    d = json.load(open(os.path.join(DGP6, 'RESULTS.json'))); comp = d['verdict_inputs']['main']['complete']; rep = sorted(comp['REPAIRED'])
    assert len(rep) == 24, 'DGP6 REPAIRED completions: %d != 24' % len(rep)
    for arm in ('BASE', 'SEED', 'GLOBAL'):
        if arm in comp: assert sorted(comp[arm]) == rep, 'DGP6 %s completion set differs from REPAIRED' % arm
    return rep, dict(source=os.path.join(DGP6, 'RESULTS.json'), source_sha256=sha(os.path.join(DGP6, 'RESULTS.json')), key='verdict_inputs.main.complete.REPAIRED', identical_across_arms=sorted(comp))

