def holdout(root):
    require_local_source(root)
    import research.campaigns.hp.dense_gen as DG
    fr = json.load(open(os.path.join(RD, 'FREEZE.json'))); head = git(root, 'rev-parse', 'HEAD'); assert head == fr['code']['commit'], 'holdout must be generated at the frozen commit (%s != %s)' % (head[:9], fr['code']['commit'][:9])
    fm = DG.generate('eval7', os.path.join(RD, 'inputs_fresh')); om = DG.generate('oracle7', os.path.join(RD, 'oracle', 'inputs_fresh'))                    # the ONLY generations of this round (after the second freeze)
    def mk(m, panel, exposure, extra=None): return dict(dict(name=m['name'], panel=panel, exposure=exposure, topology=m['topology'], n=m['n'], card=m['card'], scale=m['scale'], variant=m.get('variant'), model=m['model'], model_sha256=m['model_sha256'], evid_sha256=m['evid_sha256'], K=m['K'], edges=m['edges'], cycle_rank=m['cycle_rank'], degree=m['degree'], graph_attempts_rejected=m['graph_attempts_rejected'], exact_profile_reduction=m['exact_profile_reduction'], dynamic_range=m['dynamic_range'], seed=m['seed'], seed_record=m.get('seed_record'), tag=m['tag']), **(extra or {}))
    fresh = verify([mk(m, 'fresh_8', 'fresh (DGP7/EVAL7/; generated after the second freeze)') for m in fm]); fresh_oracle = verify([mk(m, 'oracle_fresh_4', 'fresh oracle (DGP7/ORACLE7/; generated after the second freeze; oracle only)', dict(fine_states=m['card'] ** m['n'])) for m in om])
    for t in fresh: t['name_generated'] = t['name']; t['name'] = t['name'] + '__eval7'
    for t in fresh_oracle: t['name_generated'] = t['name']; t['name'] = t['name'] + '__oracle7'
    assert sorted(t['name'] for t in fresh_oracle) == sorted(FRESH_CLIQUES_2 + FRESH_ER_2), [t['name'] for t in fresh_oracle]
    oracle32 = verify([dict(t, exposure='exposed to the oracle (DGP2 / DGP4 / DGP5 / DGP6 oracle inputs; bytes verified)') for t in json.load(open(os.path.join(DGP6, 'ORACLE_MANIFEST.json')))['tasks']]); assert len(oracle32) == 32
    o_by = {t['name']: t for t in oracle32}; exposed8 = [dict(o_by[n], panel='oracle_exposed_8', exposure='exposed strong n8 card-4 coupling-2 oracle model (bytes verified; exposed to DGP4-DGP6 oracle calculations; the three reference cliques carry the mechanism gate)') for n in EXPOSED_ORACLE_8]
    main6 = json.load(open(os.path.join(DGP6, 'MAIN_MANIFEST.json')))['tasks']; exposed68 = verify([dict(t, exposure='exposed (the 68 DGP6 main inputs: 60 DGP5 + 8 EVAL6; original bytes)', panel_dgp6=t.get('panel'), panel='exposed_68') for t in main6]); assert len(exposed68) == 68 and len({t['name'] for t in exposed68}) == 68
    pres18 = verify([dict(t, exposure='exposed (USR1 / DGP1 preservation)') for t in json.load(open(os.path.join(DGP6, 'PRESERVATION_18_MANIFEST.json')))['tasks']]); pres13 = verify([dict(t, exposure='exposed (accepted preservation panel)') for t in json.load(open(os.path.join(DGP6, 'PRESERVATION_13_MANIFEST.json')))['tasks']]); assert len(pres18) == 18 and len(pres13) == 13
    main = exposed68 + fresh; assert len(main) == 76 and len({(t['model_sha256'], t['evid_sha256']) for t in main}) == 76; byname = {t['name']: t for t in main}
    comp24, comp_src = historical_completions_24(); assert all(n in byname for n in comp24 + PINNED_HARD_8), [n for n in comp24 + PINNED_HARD_8 if n not in byname]; assert not (set(comp24) & set(PINNED_HARD_8))
    guard = [dict(byname[n], role='historical_completion') for n in comp24] + [dict(byname[n], role='pinned_hard_failure') for n in PINNED_HARD_8]; assert len(guard) == 32
    gate = [dict(byname[n], role='execution_gate_anchor') for n in GATE_ANCHORS]; p8 = [dict(byname[n], role='policy8_diagnostic') for n in POLICY8_NAMES]; assert len(gate) == 4 and len(p8) == 8
    oracle12 = exposed8 + fresh_oracle; o12_by = {t['name']: t for t in oracle12}; prio5 = PRIORITY_EXPOSED_3 + FRESH_CLIQUES_2; rest = FRESH_ER_2 + sorted([n for n in EXPOSED_ORACLE_8 if n not in prio5], key=lambda n: o12_by[n]['model_sha256']); assert len(oracle12) == 12 and set(prio5 + rest) == set(o12_by)
